def test_output_has_unified_schema_rule_id_and_rule_name(tmp_path: Path) -> None:
    """Output has top-level rule_id and rule_name (unified schema)."""
    report = tmp_path / "report.json"
    report.write_text(
        '{"type":"typo","path":"'
        + str(tmp_path / "f.txt").replace("\\", "/")
        + '","line_num":1,"byte_offset":0,"typo":"x","corrections":["y"]}\n'
    )
    (tmp_path / "f.txt").write_text("x")
    out = tmp_path / "out.json"
    data = _run_rebuild(report, out, cwd=Path(__file__).resolve().parents[1])
    assert data.get("rule_id") == "transcription_typos"
    assert "rule_name" in data
    assert "Transcription" in str(data.get("rule_name", ""))


def test_candidates_use_span_not_typo(tmp_path: Path) -> None:
    """Each candidate has span (not typo) for the matched text."""
