def test_start_index_derived_from_byte_offset(tmp_path: Path) -> None:
    """start_index is derived from byte_offset (character offset in line)."""
    report = tmp_path / "report.json"
    doc = tmp_path / "file.txt"
    line_content = "  foo bar"
    doc.write_text(line_content)
    # byte_offset 2 = start of "foo" (2 spaces)
    fpath = doc.resolve().as_posix()
    report.write_text(
        f'{{"type":"typo","path":"{fpath}","line_num":1,"byte_offset":2,"typo":"foo","corrections":["food"]}}\n'
    )
    out = tmp_path / "out.json"
    data = _run_rebuild(report, out, cwd=Path(__file__).resolve().parents[1])
    assert data["candidates"][0]["occurrences"][0]["start_index"] == 2


def test_fallback_start_index_when_byte_offset_missing(tmp_path: Path) -> None:
    """When byte_offset is missing, start_index is found by searching for span in line."""
    report = tmp_path / "report.json"
    doc = tmp_path / "nobytes.txt"
    doc.write_text("hello worrd world")
    fpath = doc.resolve().as_posix()
    # Omit byte_offset
    report.write_text(
        f'{{"type":"typo","path":"{fpath}","line_num":1,"typo":"worrd","corrections":["word"]}}\n'
    )
    out = tmp_path / "out.json"
    data = _run_rebuild(report, out, cwd=Path(__file__).resolve().parents[1])
    assert (
        data["candidates"][0]["occurrences"][0]["start_index"] == 6
    )  # "worrd" at index 6
